import json, random, subprocess, sys, time
sys.path.insert(0,'/workspace'); sys.path.insert(0,'/workspace/submission')
from protocol import validate
import fuzz

def max_case(rnd, coms=12, slots=8, edges=64, workers=1, events=64, issues=8):
    nodes = 18
    elist=[]
    pairs=set()
    # chain graph with plenty of extra forward edges
    for u in range(nodes):
        for v in range(u+1, min(nodes, u+5)):
            if len(elist)>=edges: break
            elist.append([u,v,rnd.choice([0,1,2,7,1000])])
    elist=elist[:edges]
    adj={}
    for i,(u,v,c) in enumerate(elist): adj.setdefault(u,[]).append((v,i))
    cs=[]
    for k in range(coms):
        s=rnd.randrange(0,4); t=rnd.randrange(nodes-5,nodes)
        opts=[]
        stack=[(s,[])]
        while stack:
            node,path=stack.pop()
            if len(path)>4: continue
            if node==t and path: opts.append(tuple(path)); continue
            for (nxt,e) in adj.get(node,[]):
                if nxt in [s]+[elist[x][1] for x in path]: continue
                stack.append((nxt,path+[e]))
        rnd.shuffle(opts)
        paths=[]
        used=set()
        for _ in range(slots):
            pick=None
            for o in opts:
                if o not in used: pick=o; break
            if pick: used.add(pick); paths.append(list(pick))
            else: paths.append(None)
        cs.append({'source':s,'sink':t,'demand':rnd.choice([0,1000,250,7]),'paths':paths})
    W=workers
    own=[[] for _ in range(W)]
    ids=list(range(coms)); rnd.shuffle(ids)
    for i,k in enumerate(ids): own[i%W].append(k)
    own=[sorted(o) for o in own]
    evs=[]
    tid=0
    for i in range(events):
        r=rnd.random()
        if r<0.12 and len([e for e in evs if e['op']=='issue'])<issues:
            evs.append({'op':'issue','id':tid,'worker':rnd.randrange(W)}); tid+=1
        elif r<0.30:
            issued=[e['id'] for e in evs if e['op']=='issue']
            if issued: evs.append({'op':'deliver','id':rnd.choice(issued)})
        elif r<0.75:
            evs.append({'op':'step'})
        elif r<0.85:
            evs.append({'op':'audit'})
        elif r<0.92:
            evs.append({'op':'retune','rho':rnd.randint(1,8)})
        else:
            evs.append({'op':'configure','mode':rnd.choice(['route','admit']),
                        'capacity':[[rnd.randrange(len(elist)), rnd.choice([0,1,9,1000])]],
                        'demand':[[rnd.randrange(coms), rnd.choice([0,1,1000])]],'paths':[]})
    return {'nodes':nodes,'edges':elist,'commodities':cs,'workers':own,
            'quorum':rnd.randint(1,W),'max_lag':rnd.choice([0,1,3,12]),
            'relax':[rnd.choice([1,1]),1] if rnd.random()<0.5 else [7,4],
            'rho':rnd.randint(1,8),'mode':rnd.choice(['route','admit']),'events':evs}

def build(seed):
    rnd=random.Random(seed)
    cases=[]
    total=0; issues=0
    for i in range(6):
        per=64
        iss=min(8, max(1, 48-issues))
        c=max_case(rnd, events=per, issues=iss)
        cases.append(c); total+=len(c['events']); issues+=sum(1 for e in c['events'] if e['op']=='issue')
    return {'cases':cases}

for seed in (5,6,7):
    req=build(seed)
    validate(json.loads(json.dumps(req)))
    raw=json.dumps(req,separators=(',',':'))
    tot=sum(len(c['events']) for c in req['cases']); iss=sum(1 for c in req['cases'] for e in c['events'] if e['op']=='issue')
    print('seed',seed,'events',tot,'issues',iss,'bytes',len(raw))
    t0=time.time(); p=fuzz.run_child(req)
    print('  rc',p.returncode,'seconds',round(time.time()-t0,2),'out MB',round(len(p.stdout)/1e6,3),p.stderr.decode()[:300])
